# Generated by Ingestron from the retail definitions. Do not edit: change the definitions and generate again.
# Runs after each refresh: Lakeflow pipelines cannot set tags or column
# comments, nor compare counts over all rows, so this task does.
# It also grants the tables to the principals of their roles, and with exact
# grants revokes what they do not give.
import json
import sys

from pyspark.sql import SparkSession

STATEMENTS = json.loads(r"""[
  "ALTER STREAMING TABLE `${ingestron.catalog}`.`bronze`.`customers` ALTER COLUMN `email` SET TAGS ('pii' = '', 'sensitivity' = 'confidential')"
]""")
CHECKS = json.loads(r"""[]""")
# Each table's grants, and whether to revoke the direct grants they do not give.
ACCESS = json.loads(r"""[
  {
    "table": "`${ingestron.catalog}`.`bronze`.`orders`",
    "name": "${ingestron.catalog}.bronze.orders",
    "grants": [
      {
        "principal": "${ingestron.principal_marketing_analysts}",
        "privileges": [
          "SELECT"
        ]
      },
      {
        "principal": "sales-ops",
        "privileges": [
          "SELECT",
          "MODIFY"
        ]
      },
      {
        "principal": "data-engineers",
        "privileges": [
          "SELECT",
          "MODIFY"
        ]
      }
    ],
    "exact": true
  },
  {
    "table": "`${ingestron.catalog}`.`bronze`.`customers`",
    "name": "${ingestron.catalog}.bronze.customers",
    "grants": [
      {
        "principal": "${ingestron.principal_marketing_analysts}",
        "privileges": [
          "SELECT"
        ]
      },
      {
        "principal": "team`s analysts",
        "privileges": [
          "SELECT"
        ]
      },
      {
        "principal": "data-engineers",
        "privileges": [
          "SELECT",
          "MODIFY"
        ]
      }
    ],
    "exact": true
  },
  {
    "table": "`${ingestron.catalog}`.`silver`.`daily_sales`",
    "name": "${ingestron.catalog}.silver.daily_sales",
    "grants": [
      {
        "principal": "finance",
        "privileges": [
          "SELECT"
        ]
      }
    ],
    "exact": true
  },
  {
    "table": "`${ingestron.catalog}`.`gold`.`top_customers`",
    "name": "${ingestron.catalog}.gold.top_customers",
    "grants": [],
    "exact": true
  }
]""")
# Principals whose grants are never revoked, besides the identity this task runs as.
KEEP = json.loads(r"""[
  "data-stewards"
]""")
# Values that differ between environments: the job passes each as a parameter
# ingestron.<name>=<value>, and ${ingestron.<name>} above stands for it.
VALUES = dict(argument.split("=", 1) for argument in sys.argv[1:] if "=" in argument)


def with_values(text):
    """The text with each ${ingestron.<name>} replaced by its value."""
    for name, value in VALUES.items():
        text = text.replace("${" + name + "}", value)
    return text


def passes(operator, expected, measured):
    """True when the measured count meets the rule's comparison."""
    if operator == "mustBe":
        return measured == expected
    if operator == "mustNotBe":
        return measured != expected
    if operator == "mustBeGreaterThan":
        return measured > expected
    if operator == "mustBeGreaterOrEqualTo":
        return measured >= expected
    if operator == "mustBeLessThan":
        return measured < expected
    if operator == "mustBeLessOrEqualTo":
        return measured <= expected
    low, high = expected
    inside = low <= measured <= high
    return inside if operator == "mustBeBetween" else not inside


def measure(spark, check):
    """The rule's count, in rows or as a percentage of all rows."""
    row = spark.sql(with_values(check["query"])).first()
    counted, total = row["counted"] or 0, row["total"] or 0
    if check["unit"] == "percent":
        return 0 if total == 0 else counted * 100 / total
    return counted


def quoted(principal):
    """A principal as SQL names it: in backticks, with each backtick in it doubled."""
    return "`" + principal.replace("`", "``") + "`"


def grant_statements(item):
    """The GRANT statement for each principal the table's access names."""
    return [
        f"GRANT {', '.join(grant['privileges'])} ON TABLE {item['table']} TO {quoted(grant['principal'])}"
        for grant in item["grants"]
    ]


def privilege_of(row):
    """A SHOW GRANTS row's action as REVOKE names it: upper case, with spaces."""
    return (row.get("actionType") or "").replace("_", " ").strip().upper()


def revocable(row, name, kept):
    """True for a privilege granted on the table itself to a principal not kept.

    A row the table inherits names its schema or catalog as objectKey, so it is
    kept, as are ownership, denials (DENY or DENIED, any action starting DEN)
    and any action that is not a privilege name.
    """
    action = privilege_of(row)
    return (
        (row.get("objectKey") or "").replace("`", "").lower() == name
        and action.replace(" ", "").isalpha()
        and action.isascii()
        and action not in ("OWN", "OWNERSHIP")
        and not action.startswith("DEN")
        and row["principal"].lower() not in kept
    )


def revokes(rows, item, keep):
    """The statements that take away what the table's access does not give.

    rows are the table's SHOW GRANTS rows. Each privilege granted directly on the
    table to a principal the access does not name, or that its grant does not
    give, is revoked, once. Principals compare in any letter case, so a principal
    named or kept in another case is never revoked as a stranger. ALL PRIVILEGES
    of a named principal is revoked, then its grant made again.
    """
    name = item["name"].lower()
    kept = {principal.lower() for principal in keep}
    granted = {}
    for grant in item["grants"]:
        granted.setdefault(grant["principal"].lower(), []).append(grant)
    statements = []
    for row in rows:
        if not revocable(row, name, kept):
            continue
        action = privilege_of(row)
        grants = granted.get(row["principal"].lower(), [])
        if any(action in grant["privileges"] for grant in grants):
            continue
        statements.append(f"REVOKE {action} ON TABLE {item['table']} FROM {quoted(row['principal'])}")
        if action == "ALL PRIVILEGES":
            statements.extend(grant_statements({**item, "grants": grants}))
    return list(dict.fromkeys(statements))


def with_item_values(item):
    """The table's access with each ${ingestron.<name>} replaced, before it is quoted."""
    grants = [{**grant, "principal": with_values(grant["principal"])} for grant in item["grants"]]
    names = {"table": with_values(item["table"]), "name": with_values(item["name"])}
    return {**item, **names, "grants": grants}


def apply_access(spark):
    """Grants each table's access; with exact grants, then revokes what it does not give."""
    keep = [with_values(principal) for principal in KEEP]
    keep.append(spark.sql("SELECT session_user()").first()[0])
    for item in map(with_item_values, ACCESS):
        for statement in grant_statements(item):
            spark.sql(statement)
        if item["exact"]:
            shown = spark.sql(f"SHOW GRANTS ON TABLE {item['table']}").collect()
            for statement in revokes([row.asDict() for row in shown], item, keep):
                spark.sql(statement)


def main():
    spark = SparkSession.builder.getOrCreate()
    for statement in STATEMENTS:
        spark.sql(with_values(statement))
    apply_access(spark)
    failures = []
    for check in CHECKS:
        measured = measure(spark, check)
        if passes(check["operator"], check["value"], measured):
            continue
        message = f'{with_values(check["table"])}: {check["name"]} measured {measured}, expected {check["operator"]} {check["value"]}'
        if check["action"] == "fail":
            failures.append(message)
        else:
            print(f"Warning: {message}")
    if failures:
        raise RuntimeError("Table checks failed:\n" + "\n".join(failures))


main()
